  values ('ME', 'short_answer', 'What is the difference between saprophytic and saprozoic nutrition? (3 marks)', 'Saprophytic nutrition is found in fungi and many bacteria: they live on dead and decaying organic matter, secrete digestive enzymes onto it, digest it outside their bodies and then absorb the simple soluble products (e.g. Rhizopus, mushrooms). Saprozoic nutrition is found in some animals and protozoans (e.g. Monocystis and some free-living protozoa): they absorb organic matter that is already dissolved, from decaying material or the surrounding fluid, directly through their body surface without digesting solid food outside.', null, '[{"point": "Saprophytic: organisms (fungi, many bacteria) secrete enzymes onto dead organic matter, digest it outside the body and absorb the soluble products", "marks": 1.5}, {"point": "Saprozoic: animals/ protozoans absorb already dissolved organic matter (decayed matter) through their body surface, e.g. some protozoa, tapeworm-like absorption", "marks": 1.5}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'bio-science-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
