with nq as (
  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'short_answer', 'In dim light you can see better by looking through the corner of the eye. Why? (3 marks)', 'The retina has two kinds of photoreceptors: cones, which work in bright light and give colour and detail, and rods, which contain rhodopsin and are very sensitive, working in dim light. The centre of the retina, the fovea of the yellow spot, contains only cones, while rods are most numerous in the peripheral parts of the retina. When we look at an object from the corner of the eye in dim light, its image falls on the peripheral retina, where the rods are concentrated, so it is seen better than when looked at directly (when the image falls on the cone-only fovea).', null, '[{"point": "Rods (contain rhodopsin) work in dim light; cones need bright light", "marks": 1}, {"point": "Fovea/ yellow spot at the centre has only cones; rods are concentrated in the periphery of the retina", "marks": 1}, {"point": "Looking from the corner focuses the image on the peripheral retina rich in rods, giving better dim-light (scotopic) vision", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
