  values ('ME', 'short_answer', 'Define the term polymer. Give the names of one natural polymer and one synthetic polymer and mention the monomers present in them. (3 marks)', 'A polymer is a very large molecule (macromolecule) formed by joining a large number of small repeating units called monomers through covalent bonds (polymerisation). Natural polymer: starch (or cellulose), whose monomer is glucose (natural rubber is made of isoprene, proteins of amino acids). Synthetic polymer: polythene (polyethylene), whose monomer is ethene, CH2=CH2 (PVC from vinyl chloride; nylon-6,6 from hexamethylenediamine and adipic acid).', null, '[{"point": "Polymer: a very large molecule (macromolecule) made by joining many small repeating units (monomers) by covalent bonds", "marks": 1}, {"point": "Natural polymer and its monomer, e.g. starch/ cellulose - glucose; protein - amino acids; natural rubber - isoprene", "marks": 1}, {"point": "Synthetic polymer and its monomer, e.g. polythene - ethene; PVC - vinyl chloride; nylon-6,6 - hexamethylenediamine and adipic acid", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
